INSERT INTO public.library_phrases (text_pt, text_en, text_es, category, is_active) VALUES
('Você sabia que o arco-íris tem 7 cores?', 'Did you know the rainbow has 7 colors?', '¿Sabías que el arcoíris tiene 7 colores?', 'education', true),
('Vou te dizer todas as cores do arco-íris: Vermelho, Laranja, Amarelo, Verde, Azul, Anil e Violeta. Começa no vermelho e termina no violeta.', 'I''ll tell you all the colors of the rainbow: Red, Orange, Yellow, Green, Blue, Indigo and Violet. It starts with red and ends with violet.', 'Te diré todos los colores del arcoíris: Rojo, Naranja, Amarillo, Verde, Azul, Índigo y Violeta. Empieza en el rojo y termina en el violeta.', 'education', true),
('Você sabia que os polvos têm 3 corações?', 'Did you know octopuses have 3 hearts?', '¿Sabías que los pulpos tienen 3 corazones?', 'education', true),
('Vamos contar de 0 a 10?', 'Let''s count from 0 to 10!', '¡Vamos a contar de 0 a 10!', 'education', true),
('E agora vamos de 10 a 0?', 'And now let''s go from 10 to 0!', '¿Y ahora vamos de 10 a 0?', 'education', true),
('Vou te contar uma coisa bem legal, sabia que a coruja consegue virar a cabeça quase toda para trás?', 'I''ll tell you something really cool, did you know owls can turn their head almost all the way around?', '¡Te voy a contar algo muy genial, sabías que el búho puede girar la cabeza casi hasta atrás?', 'education', true),
('A formiga é muito forte e pode carregar coisas maiores que ela, sabia disso?', 'Ants are very strong and can carry things bigger than themselves, did you know that?', '¡La hormiga es muy fuerte y puede cargar cosas más grandes que ella, sabías eso?', 'education', true),
('O arco-íris é muito lindo, ele aparece quando o sol e a chuva brincam juntos.', 'The rainbow is very beautiful, it appears when the sun and rain play together.', 'El arcoíris es muy lindo, aparece cuando el sol y la lluvia juegan juntos.', 'education', true),
('A água é tão importante para nós e para as plantas também, mas as plantas bebem água pelas raízes, sabia?', 'Water is so important for us and for plants too, but plants drink water through their roots, did you know?', 'El agua es muy importante para nosotros y para las plantas también, pero las plantas beben agua por las raíces, ¿sabías?', 'education', true),
('Você sabe que as nuvens são feitas de gotinhas de água!', 'Did you know clouds are made of tiny water droplets!', '¡Sabías que las nubes están hechas de gotitas de agua!', 'education', true),
('O sol brilha muito né? Ele ajuda as plantinhas a crescerem.', 'The sun shines so bright, right? It helps the little plants grow.', 'El sol brilla mucho, ¿verdad? Él ayuda a las plantitas a crecer.', 'education', true),
('O coração faz tum-tum o dia todo! Ele trabalha sem parar para cuidar da gente!', 'The heart goes thump-thump all day! It works non-stop to take care of us!', '¡El corazón hace tum-tum todo el día! ¡Trabaja sin parar para cuidarnos!', 'education', true),
('Olha quantos dedinhos temos na mão! Eles ajudam a pegar brinquedos e desenhar.', 'Look how many little fingers we have on our hand! They help us grab toys and draw.', '¡Mira cuántos deditos tenemos en la mano! Nos ayudan a agarrar juguetes y dibujar.', 'education', true),
('Você sabia que precisamos dormir bem para crescer?', 'Did you know we need to sleep well to grow?', '¿Sabías que necesitamos dormir bien para crecer?', 'education', true),
('Sabe por que fica escuro à noite? Porque o sol vai iluminar o outro lado da Terra!', 'Do you know why it gets dark at night? Because the sun goes to light up the other side of the Earth!', '¿Sabes por qué se oscurece de noche? ¡Porque el sol va a iluminar el otro lado de la Tierra!', 'education', true),
('Sabe o que acontece se misturar azul e amarelo? Fica verde! As cores gostam de brincar.', 'Do you know what happens if you mix blue and yellow? It turns green! Colors like to play.', '¿Sabes qué pasa si mezclas azul y amarillo? ¡Se pone verde! A los colores les gusta jugar.', 'education', true),
('Se misturar vermelho e amarelo, fica laranja!', 'If you mix red and yellow, it turns orange!', '¡Si mezclas rojo y amarillo, se pone naranja!', 'education', true),
('Se misturar vermelho e azul, fica roxo ou violeta!', 'If you mix red and blue, it turns purple or violet!', '¡Si mezclas rojo y azul, se pone morado o violeta!', 'education', true),
('Tem um animal que não consegue pular, sabe qual é? O elefante! Ele é o único animal que não consegue pular!', 'There''s an animal that can''t jump, do you know which one? The elephant! It''s the only animal that can''t jump!', '¿Hay un animal que no puede saltar, sabes cuál es? ¡El elefante! ¡Es el único animal que no puede saltar!', 'education', true),
('As girafas não gostam de dormir, sabia que elas dormem só 20 a 30 minutos por dia?', 'Giraffes don''t like to sleep, did you know they only sleep 20 to 30 minutes a day?', 'A las jirafas no les gusta dormir, ¿sabías que duermen solo 20 a 30 minutos al día?', 'education', true),
('O coração da baleia azul é tão grande quanto um carro pequeno!', 'The blue whale''s heart is as big as a small car!', '¡El corazón de la ballena azul es tan grande como un carro pequeño!', 'education', true),
('Dentro da nossa cabeça tem o cérebro e ele nunca dorme, nem quando estamos dormindo.', 'Inside our head there''s the brain and it never sleeps, not even when we''re sleeping.', 'Dentro de nuestra cabeza está el cerebro y nunca duerme, ni cuando estamos dormidos.', 'education', true),
('Nossos ossos são muito fortes, mais fortes que o aço!', 'Our bones are very strong, stronger than steel!', '¡Nuestros huesos son muy fuertes, más fuertes que el acero!', 'education', true),
('Sabia que a Terra gira sem parar, mesmo quando dormimos?', 'Did you know the Earth spins non-stop, even when we sleep?', '¿Sabías que la Tierra gira sin parar, incluso cuando dormimos?', 'education', true),
('A gente precisa comer cenoura, ela ajuda nossos olhos a enxergarem melhor.', 'We need to eat carrots, they help our eyes see better.', 'Necesitamos comer zanahoria, ayuda a nuestros ojos a ver mejor.', 'education', true),
('Você sabia que o mel vem das abelhas e é um docinho natural?', 'Did you know honey comes from bees and is a natural sweetie?', '¿Sabías que la miel viene de las abejas y es un dulcecito natural?', 'education', true),
('O pão e o bolo crescem no forno quentinho, por causa de um pozinho mágico chamado fermento.', 'Bread and cake grow in the warm oven, because of a magic powder called yeast.', 'El pan y el pastel crecen en el horno calientito, por un polvito mágico llamado levadura.', 'education', true),
('Você sabia que o milho vira pipoca? É só esquentar! Ele estoura e vira pipoca!', 'Did you know corn turns into popcorn? Just heat it up! It pops and turns into popcorn!', '¿Sabías que el maíz se convierte en palomitas? ¡Solo hay que calentarlo! ¡Explota y se convierte en palomitas!', 'education', true),
('O tomate é vermelho e tem suquinho dentro dele, delicioso!', 'The tomato is red and has yummy juice inside, delicious!', '¡El tomate es rojo y tiene juguito adentro, delicioso!', 'education', true),
('A alface é uma delícia, ajuda o corpo a ficar forte. Sabia?', 'Lettuce is delicious, it helps the body stay strong. Did you know?', 'La lechuga es deliciosa, ayuda al cuerpo a estar fuerte. ¿Sabías?', 'education', true),
('O círculo é redondo e não tem lados!', 'The circle is round and has no sides!', '¡El círculo es redondo y no tiene lados!', 'education', true),
('A roda e o prato são círculos, já viu isso?', 'The wheel and the plate are circles, have you noticed that?', 'La rueda y el plato son círculos, ¿ya viste eso?', 'education', true),
('Onde você vê um círculo aí?', 'Where do you see a circle there?', '¿Dónde ves un círculo ahí?', 'education', true),
('O quadrado tem 4 lados iguais.', 'The square has 4 equal sides.', 'El cuadrado tiene 4 lados iguales.', 'education', true),
('A janela e o dado são quadrados!', 'The window and the dice are squares!', '¡La ventana y el dado son cuadrados!', 'education', true),
('Conta comigo: 1, 2, 3, 4!', 'Count with me: 1, 2, 3, 4!', '¡Cuenta conmigo: 1, 2, 3, 4!', 'education', true),
('O triângulo tem 3 lados e 3 pontinhas.', 'The triangle has 3 sides and 3 little points.', 'El triángulo tiene 3 lados y 3 puntitas.', 'education', true),
('O telhado da casa parece um triângulo!', 'The roof of the house looks like a triangle!', '¡El techo de la casa parece un triángulo!', 'education', true),
('Quantos lados tem o triângulo?', 'How many sides does the triangle have?', '¿Cuántos lados tiene el triángulo?', 'education', true),
('O retângulo tem 4 lados, mas dois são maiores.', 'The rectangle has 4 sides, but two are bigger.', 'El rectángulo tiene 4 lados, pero dos son más grandes.', 'education', true),
('A porta e o livro são retângulos!', 'The door and the book are rectangles!', '¡La puerta y el libro son rectángulos!', 'education', true),
('Você achou um aí?', 'Did you find one there?', '¿Encontraste uno ahí?', 'education', true),
('Um dia inteiro tem 24 horas. 12 horas de dia e 12 horas de noite. Você sabia disso?', 'A whole day has 24 hours. 12 hours of day and 12 hours of night. Did you know that?', 'Un día entero tiene 24 horas. 12 horas de día y 12 horas de noche. ¿Sabías eso?', 'education', true);